from decimal import Decimal

def simple_exponential_notation(x):
    dec_x = Decimal(x)
    if dec_x == int(dec_x):
        return str(int(dec_x))
    else:
        exp_x = dec_x.to_eng_string()
        if 'e' not in exp_x:
            return exp_x
        mantissa, exponent = exp_x.split('e')
        if int(exponent) == 0:
            return mantissa
        else:
            return f"{mantissa}E{exponent}"

