def simple_exponential_notation(x):
    from fractions import Fraction
    num = Fraction(x).limit_denominator()
    a, b = str(num).split('.')
    if b == '0':
        return f"{int(a)}E{len(b) - 1}"
    else:
        while b[-1] == '0':
            b = b[:-1]
        return f"{int(a)}.{b}E{len(b)}"

