import sys

def simple_exponential_notation(x):
    # Convert the input string to a float
    num = float(x)

    # Handle special cases
    if num == 0:
        return "0"
    elif num.is_integer():
        return str(int(num))

    # Get the exponent and mantissa using logarithm base 10
    import math
    exp = int(math.log10(abs(num)))
    mantissa = abs(num) / (10 ** exp)

    # Format the result
    if exp != 0:
        return f"{mantissa}E{exp}"
    else:
        return str(mantissa)

