def simple_exponential_notation(x):
    import math
    if '.' in x:
        a, b = map(int, x.split('.'))
        e = len(str(b))
        if a == 0:
            return f"{b}E{e}"
        else:
            while a % 10 == 0:
                a //= 10
                e += 1
            return f"{a}E{e}"
    else:
        return x

